def build_agent(sandbox):
    # Chassis (torso) at starting position
    chassis = sandbox.add_beam(
        x=10.0, y=2.0, width=0.5, height=0.2, angle=0, density=1.0
    )

    # Wheel radius and density
    wheel_radius = 0.2
    wheel_density = 0.5

