import math

def _get_joints(agent_components):
    if isinstance(agent_components, dict):
        return agent_components.get("joints", [])
    return []

def build_agent(sandbox):
    # Create lightweight torso at starting position
    torso = sandbox.add_beam(
        x=10.0, y=2.0, width=0.2, height=0.2, angle=0, density=1.0
    )

    # Create legs with optimal dimensions for mass and ground contact
    leg_width = 0.1
    leg_height = 2.0  # Ensures bottom of leg reaches y=1.0
    leg_density = 0.5

    # Left leg (centered at x=9.0, y=2.0)
    leg1 = sandbox.add_beam(
        x=9.0, y=2.0, width=leg_width, height=leg_height, angle=0, density=leg_density
    )

    # Right leg (centered at x=11.0, y=2.0)
    leg2 = sandbox.add_beam(
        x=11.0, y=2.0, width=leg_width, height=leg_height, angle=0, density=leg_density
    )

    # Connect legs to torso with pivot joints
    joint1 = sandbox.add_joint(
        torso, leg1, anchor_point=(9.0, 2.0), type='pivot'
    )
    joint2 = sandbox.add_joint(
        torso, leg2, anchor_point=(11.0, 2.0), type='pivot'
    )

    # Set maximum friction to ensure traction without exceeding the cap
    sandbox.set_material_properties(torso, friction=0.8)
    sandbox.set_material_properties(leg1, friction=0.8)
    sandbox.set_material_properties(leg2, friction=0.8)

    return {
        "body": torso,
        "joints": [joint1, joint2]
    }

def agent_action(sandbox, agent_body, step_count):
    joints = _get_joints(agent_body)

    # Drive both legs forward with consistent motor speed
    for j in joints:
        sandbox.set_motor(j, motor_speed=2.0, max_torque=100.0)
